@extends('layouts.app') @section('title','Audit Logs') @section('page-title','Audit Logs')
@section('content')<div x-data="auditLog({{ Illuminate\Support\Js::from($entries) }})" class="space-y-4"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><input x-model.debounce.300ms="search" placeholder="Search logs" aria-label="Search audit logs" class="rounded border p-2.5"><select x-model="category" class="rounded border p-2.5"><option value="">All categories</option>@foreach($categories as $cat)<option>{{ $cat }}</option>@endforeach</select><input type="date" x-model="start" aria-label="Start date" class="rounded border p-2.5"><input type="date" x-model="end" aria-label="End date" class="rounded border p-2.5"></div><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-gray-50"><tr>@foreach(['Timestamp','User Name','Role','Action Category','Description','Affected Record','Details'] as $h)<th class="p-3">{{ $h }}</th>@endforeach</tr></thead><tbody><template x-for="r in pageRows" :key="r.id"><tr class="border-t"><td class="p-3" x-text="r.created_at"></td><td class="p-3" x-text="r.user_name"></td><td class="p-3" x-text="r.role"></td><td class="p-3" x-text="r.action_category"></td><td class="p-3" x-text="r.description"></td><td class="p-3" x-text="r.affected_record"></td><td class="p-3"><button @click="selected=r;open=true" class="text-teal-800 underline">View Details</button></td></tr></template><tr x-show="!filtered.length"><td colspan="7" class="p-8 text-center text-gray-700" x-text="`No audit logs found${search?' for “'+search+'”':''}.`"></td></tr></tbody></table></div><div x-show="filtered.length>20" class="flex justify-between text-sm"><span x-text="`Page ${page} of ${pages}`"></span><div><button @click="page=Math.max(1,page-1)" class="rounded border px-3 py-2">Previous</button> <button @click="page=Math.min(pages,page+1)" class="rounded border px-3 py-2">Next</button></div></div><div x-show="open" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div class="w-full max-w-2xl rounded-xl bg-white p-6" x-trap.inert.noscroll="open" role="dialog" aria-modal="true"><h2 class="text-lg font-semibold">Audit log details</h2><p class="my-3 text-sm" x-text="selected?.description"></p><div class="grid gap-4 sm:grid-cols-2"><div><h3 class="font-semibold">Before</h3><pre class="mt-2 whitespace-pre-wrap text-sm" x-text="selected?.before_values?JSON.stringify(selected.before_values,null,2):'No before/after data available.'"></pre></div><div><h3 class="font-semibold">After</h3><pre class="mt-2 whitespace-pre-wrap text-sm" x-text="selected?.after_values?JSON.stringify(selected.after_values,null,2):'No before/after data available.'"></pre></div></div><button @click="open=false" class="mt-4 rounded border px-4 py-2">Close</button></div></div></div><script>function auditLog(rows){return {rows,search:'',category:'',start:'',end:'',page:1,open:false,selected:null,get filtered(){let q=this.search.toLowerCase();return this.rows.filter(r=>(!q||(r.user_name+' '+r.description+' '+r.affected_record).toLowerCase().includes(q))&&(!this.category||r.action_category===this.category)&&(!this.start||r.created_at.slice(0,10)>=this.start)&&(!this.end||r.created_at.slice(0,10)<=this.end))},get pages(){return Math.max(1,Math.ceil(this.filtered.length/20))},get pageRows(){return this.filtered.slice((this.page-1)*20,this.page*20)}}}</script>@endsection
